package rw.umurava.emergency;

import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import rw.umurava.community.CommunityMembershipRepository;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.UUID;

@Service
public class EmergencyService {
 private static final String ACTIVE="ACTIVE"; private final JdbcTemplate jdbc; private final CommunityMembershipRepository memberships;
 public EmergencyService(JdbcTemplate jdbc,CommunityMembershipRepository memberships){this.jdbc=jdbc;this.memberships=memberships;}
 @Transactional(readOnly=true) public List<Map<String,Object>> incidents(UUID user,UUID community){member(user,community);return jdbc.queryForList("SELECT id,incident_type,description,severity,status,latitude,longitude,created_at,updated_at,resolved_at FROM emergency_incidents WHERE community_id=? ORDER BY CASE severity WHEN 'CRITICAL' THEN 0 WHEN 'HIGH' THEN 1 WHEN 'MEDIUM' THEN 2 ELSE 3 END,created_at DESC",community);}
 @Transactional public Map<String,Object> report(UUID user,UUID community,String type,String description,String severity,Double lat,Double lon){member(user,community);if(!Set.of("LOW","MEDIUM","HIGH","CRITICAL").contains(severity))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid incident severity");UUID id=UUID.randomUUID();jdbc.update("INSERT INTO emergency_incidents(id,community_id,reported_by,incident_type,description,severity,status,latitude,longitude) VALUES (?,?,?,?,?,?,'REPORTED',?,?)",id,community,user,type.trim(),description,severity,lat,lon);jdbc.update("INSERT INTO incident_updates(id,incident_id,community_id,actor_user_id,new_status,note) VALUES (?,?,?,?,?,?)",UUID.randomUUID(),id,community,user,"REPORTED","Incident submitted");return jdbc.queryForMap("SELECT id,incident_type,description,severity,status,latitude,longitude,created_at FROM emergency_incidents WHERE id=?",id);}
 @Transactional public Map<String,Object> updateIncident(UUID user,UUID community,UUID id,String status,String note){role(user,community,"COMMUNICATIONS_OFFICER");var rows=jdbc.query("SELECT status FROM emergency_incidents WHERE id=? AND community_id=? FOR UPDATE",(rs,n)->rs.getString(1),id,community);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Incident not found");String previous=rows.getFirst();boolean valid=(previous.equals("REPORTED")&&status.equals("ACKNOWLEDGED"))||(previous.equals("ACKNOWLEDGED")&&status.equals("RESPONDING"))||(previous.equals("RESPONDING")&&status.equals("RESOLVED"))||(previous.equals("RESOLVED")&&status.equals("CLOSED"));if(!valid)throw new ResponseStatusException(HttpStatus.CONFLICT,"Invalid incident status transition");jdbc.update("UPDATE emergency_incidents SET status=?,updated_at=NOW(),resolved_at=CASE WHEN ?='RESOLVED' THEN NOW() ELSE resolved_at END WHERE id=? AND community_id=?",status,status,id,community);jdbc.update("INSERT INTO incident_updates(id,incident_id,community_id,actor_user_id,previous_status,new_status,note) VALUES (?,?,?,?,?,?,?)",UUID.randomUUID(),id,community,user,previous,status,note);return jdbc.queryForMap("SELECT id,incident_type,severity,status,updated_at,resolved_at FROM emergency_incidents WHERE id=?",id);}
 @Transactional(readOnly=true) public List<Map<String,Object>> announcements(UUID user,UUID community){member(user,community);return jdbc.queryForList("SELECT a.id,a.title,a.message,a.priority,a.starts_at,a.expires_at,a.created_at,CASE WHEN r.user_id IS NULL THEN FALSE ELSE TRUE END AS acknowledged FROM community_announcements a LEFT JOIN announcement_receipts r ON r.announcement_id=a.id AND r.user_id=? WHERE a.community_id=? AND a.starts_at<=NOW() AND (a.expires_at IS NULL OR a.expires_at>NOW()) ORDER BY CASE a.priority WHEN 'CRITICAL' THEN 0 WHEN 'HIGH' THEN 1 ELSE 2 END,a.starts_at DESC",user,community);}
 @Transactional public Map<String,Object> publish(UUID user,UUID community,String title,String message,String priority,java.time.Instant expiresAt){role(user,community,"COMMUNICATIONS_OFFICER");if(!Set.of("LOW","NORMAL","HIGH","CRITICAL").contains(priority))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid announcement priority");if(expiresAt!=null&&!expiresAt.isAfter(java.time.Instant.now()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Expiry must be in the future");UUID id=UUID.randomUUID();jdbc.update("INSERT INTO community_announcements(id,community_id,title,message,priority,expires_at,published_by) VALUES (?,?,?,?,?,?,?)",id,community,title.trim(),message,priority,expiresAt,user);return jdbc.queryForMap("SELECT id,title,message,priority,starts_at,expires_at,created_at FROM community_announcements WHERE id=?",id);}
 @Transactional public int acknowledge(UUID user,UUID community,UUID announcement){member(user,community);int n=jdbc.update("INSERT INTO announcement_receipts(announcement_id,user_id) SELECT ?,? WHERE EXISTS(SELECT 1 FROM community_announcements WHERE id=? AND community_id=? AND starts_at<=NOW() AND (expires_at IS NULL OR expires_at>NOW())) ON CONFLICT DO NOTHING",announcement,user,announcement,community);if(n==0){Integer exists=jdbc.queryForObject("SELECT COUNT(*) FROM community_announcements WHERE id=? AND community_id=?",Integer.class,announcement,community);if(exists==null||exists==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Announcement not found");}return n;}
 private void member(UUID user,UUID community){if(!memberships.existsByUserIdAndCommunityIdAndStatus(user,community,ACTIVE))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Active community membership required");}
 private void role(UUID user,UUID community,String required){if(!memberships.existsByUserIdAndCommunityIdAndStatus(user,community,ACTIVE)||(!memberships.existsByUserIdAndCommunityIdAndRoleAndStatus(user,community,required,ACTIVE)&&!memberships.existsByUserIdAndCommunityIdAndRoleAndStatus(user,community,"COMMUNITY_ADMIN",ACTIVE)))throw new ResponseStatusException(HttpStatus.FORBIDDEN,required+" or community administrator role required");}
}
